//! Multiple monotonic clocks. Persisted sessions resume paused, never fabricate elapsed time.
use serde::{Serialize,Deserialize};use serde_json::{Value,json};use std::path::PathBuf;
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(rename_all="camelCase")]
pub struct Timer{pub id:String,pub name:String,pub mode:String,pub duration:u64,pub focus:u64,pub rest:u64,pub rounds:u32,pub round:u32,pub phase:String,pub elapsed_ms:u64,pub running:bool,pub finished:bool}
impl Timer{
 pub fn limit_ms(&self)->u64{1000*if self.mode=="pomodoro"{if self.phase=="rest"{self.rest}else{self.focus}}else{self.duration}}
 pub fn remaining_ms(&self)->u64{self.limit_ms().saturating_sub(self.elapsed_ms)}
 pub fn clock(&self)->String{format_time(if self.mode=="stopwatch"{self.elapsed_ms/1000}else{self.remaining_ms().div_ceil(1000)})}
 pub fn progress(&self)->f64{if self.mode=="stopwatch"{(self.elapsed_ms%60000)as f64/60000.}else{(self.elapsed_ms as f64/self.limit_ms().max(1)as f64).clamp(0.,1.)}}
 pub fn subtitle(&self)->String{if self.finished{return "已完成".into()}let phase=if self.mode=="pomodoro"{format!("{} · 第 {} / {} 轮",if self.phase=="focus"{"专注"}else{"休息"},self.round,self.rounds)}else if self.mode=="stopwatch"{"正向计时".into()}else{"倒计时".into()};format!("{phase}{}",if self.running{""}else{" · 已暂停"})}
 fn advance(&mut self,ms:u64)->bool{if !self.running||self.finished{return false}self.elapsed_ms=self.elapsed_ms.saturating_add(ms);if self.mode=="stopwatch"{return false}let mut changed=false;while self.elapsed_ms>=self.limit_ms(){let limit=self.limit_ms();self.elapsed_ms-=limit;changed=true;if self.mode!="pomodoro"||(self.phase=="focus"&&self.round>=self.rounds){self.running=false;self.finished=true;self.elapsed_ms=limit;break}if self.phase=="focus"{self.phase="rest".into()}else{self.phase="focus".into();self.round+=1;}}changed}
}
pub fn format_time(s:u64)->String{if s>=3600{format!("{:02}:{:02}:{:02}",s/3600,s/60%60,s%60)}else{format!("{:02}:{:02}",s/60,s%60)}}
pub struct Store{path:PathBuf,pub items:Vec<Timer>,pub error:Option<String>}
impl Store{
 pub fn new(path:PathBuf)->Self{let mut s=Self{path,items:vec![],error:None};if s.path.is_file(){match std::fs::read(&s.path).map_err(|e|e.to_string()).and_then(|b|serde_json::from_slice::<Vec<Timer>>(&b).map_err(|e|e.to_string())){Ok(mut items)=>{for t in &mut items{t.running=false;}if items.len()<=8&&items.iter().all(|t|matches!(t.mode.as_str(),"countdown"|"pomodoro"|"stopwatch")&&t.duration>0&&t.focus>0&&t.rest>0&&(1..=16).contains(&t.rounds)){s.items=items}else{s.error=Some("计时数据无效，原文件已保留".into())}},Err(e)=>s.error=Some(e)}}s}
 pub fn persist(&self)->Result<(),String>{if let Some(e)=&self.error{return Err(e.clone())}if self.path.as_os_str().is_empty(){return Ok(())}lyric_backend::io::save_settings(&self.path,&json!(self.items))}
 pub fn list(&self)->Value{json!(self.items.iter().map(|t|{let mut v=json!(t);v["clock"]=json!(t.clock());v["subtitle"]=json!(t.subtitle());v["progress"]=json!(t.progress());v}).collect::<Vec<_>>())}
 pub fn create(&mut self,v:&Value)->Result<String,String>{if self.items.len()>=8{return Err("最多同时保留 8 个计时器，请先移除不用的项目".into())}let mode=v["mode"].as_str().unwrap_or("countdown");if !matches!(mode,"countdown"|"pomodoro"|"stopwatch"){return Err("未知计时模式".into())}let number=|key,default,max|->Result<u64,String>{match v.get(key){Some(value)=>value.as_u64().filter(|n|*n>=1&&*n<=max).ok_or_else(||format!("{key} 超出有效范围")),None=>Ok(default)}};let duration=number("duration",300,86400)?;let focus=number("focus",1500,14400)?;let rest=number("rest",300,3600)?;let rounds=number("rounds",4,16)?as u32;let name=v["name"].as_str().unwrap_or("").trim();if name.chars().count()>60||name.chars().any(char::is_control){return Err("计时器名称过长或包含无效字符".into())}let name=if name.is_empty(){match mode{"pomodoro"=>"番茄钟","stopwatch"=>"正向计时",_=>"倒计时"}}else{name};let id=format!("clock-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_nanos());self.items.push(Timer{id:id.clone(),name:name.into(),mode:mode.into(),duration,focus,rest,rounds,round:1,phase:"focus".into(),elapsed_ms:0,running:true,finished:false});if let Err(e)=self.persist(){self.items.pop();return Err(e)}Ok(id)}
 pub fn action(&mut self,id:&str,action:&str)->Result<(),String>{let old=self.items.clone();if action=="delete"{if !self.items.iter().any(|t|t.id==id){return Err("计时器不存在".into())}self.items.retain(|t|t.id!=id);}else{let t=self.items.iter_mut().find(|t|t.id==id).ok_or("计时器不存在")?;match action{"toggle"=>{if t.finished{t.finished=false;t.elapsed_ms=0;t.round=1;t.phase="focus".into();}t.running=!t.running},"reset"=>{t.running=false;t.finished=false;t.elapsed_ms=0;t.round=1;t.phase="focus".into();},_=>return Err("未知计时操作".into())}}if let Err(e)=self.persist(){self.items=old;return Err(e)}Ok(())}
 pub fn advance(&mut self,ms:u64)->Vec<Timer>{let mut events=vec![];for t in &mut self.items{if t.advance(ms){events.push(t.clone());}}events}
}
#[cfg(test)]mod tests{use super::*;fn store()->Store{Store::new(PathBuf::new())}
 #[test]fn pause_resume_and_countdown_complete_exactly_once(){let mut s=store();let id=s.create(&json!({"mode":"countdown","duration":2})).unwrap();s.advance(900);s.action(&id,"toggle").unwrap();s.advance(5000);assert_eq!(s.items[0].clock(),"00:02");s.action(&id,"toggle").unwrap();assert_eq!(s.advance(1100).len(),1);assert!(s.advance(5000).is_empty());assert_eq!(s.items[0].clock(),"00:00");}
 #[test]fn pomodoro_handles_a_sleep_sized_gap_without_alert_flood(){let mut s=store();s.create(&json!({"mode":"pomodoro","focus":2,"rest":1,"rounds":3})).unwrap();assert_eq!(s.advance(7000).len(),1);assert_eq!(s.items[0].round,3);assert_eq!(s.items[0].phase,"focus");assert!(!s.items[0].finished);assert_eq!(s.advance(1000).len(),1);assert!(s.items[0].finished);}
 #[test]fn concurrent_clocks_keep_independent_state_and_validate_input(){let mut s=store();let id=s.create(&json!({"mode":"stopwatch"})).unwrap();s.create(&json!({"duration":5})).unwrap();s.advance(5000);assert_eq!(s.items[0].clock(),"00:05");assert!(s.items[1].finished);s.action(&id,"reset").unwrap();assert_eq!(s.items[0].clock(),"00:00");assert!(s.create(&json!({"duration":0})).is_err());assert!(s.create(&json!({"rounds":17})).is_err());}
}
